//! Contracts of the oscillators family, from `tests/fixtures/contract_oscillators.txt`
//! (generated by `reference/kestrel_reference/fixtures/contract_oscillators.py`).
//!
//! Conventions the type documentation leaves open are stated in the generator's docstring. Not
//! specified here: the context lines and trend-wedge alerts of `stoch_rsi`, `cci`, `williams_r`
//! and `fisher_transform` (they only start after a fixed context window of 40-100 bars; every case
//! ends before), the CCI exhaustion alerts (200 bars of line history), and source mapping.

use super::Status::{Partial, Specified};
use super::{assert_holds, assert_rejected, Coverage};
use crate::common::contract::load;
use kestrel_chartkit::IndicatorUnit;

const FIXTURE: &str = include_str!("../fixtures/contract_oscillators.txt");

fn holds(name: &str, indicator: &str, unit: IndicatorUnit) {
    assert_holds(&load(FIXTURE, name, indicator, unit));
}

/// Indicators of this family whose contract is not yet written. Moved into [`COVERAGE`] once
/// their cases exist; a name in neither list fails the matrix.
pub const PENDING: &[&str] = &[];

pub const COVERAGE: &[Coverage] = &[
    Coverage::full("macd"),
    Coverage {
        indicator: "stoch_rsi",
        values: Partial("the ctx line (from bar 100 + k_len - 1) is not reached by any case"),
        alerts: Partial("extreme and mid crosses; the trend wedge needs the ctx line"),
        configuration: Specified,
    },
    Coverage {
        indicator: "cci",
        values: Partial("the ctx line (from bar 100) is not reached by any case"),
        alerts: Partial(
            "extreme and zero crosses; the trend wedge needs the ctx line, exhaustion 200 bars",
        ),
        configuration: Specified,
    },
    Coverage::full("mfi"),
    Coverage::full("pmo"),
    Coverage::full("smi"),
    Coverage::full("rci"),
    Coverage::full("trix"),
    Coverage {
        indicator: "williams_r",
        values: Partial("the ctx line (from bar 50) is not reached by any case"),
        alerts: Partial("extreme and mid crosses; the trend wedge needs the ctx line"),
        configuration: Specified,
    },
    Coverage {
        indicator: "tsi",
        values: Specified,
        alerts: Partial(
            "divergence rule undocumented on the type; cases pin an assumed 4-bar slope rule",
        ),
        configuration: Specified,
    },
    Coverage {
        indicator: "fisher_transform",
        values: Partial("the ctx line (from bar 40) is not reached by any case"),
        alerts: Partial("extreme and mid crosses; the trend wedge needs the ctx line"),
        configuration: Specified,
    },
    Coverage {
        indicator: "stochastic",
        values: Specified,
        alerts: Partial("alert rule undocumented on the type; cases pin the assumed 20/80 rule"),
        configuration: Specified,
    },
    Coverage::full("roc"),
    Coverage::full("ultimate_oscillator"),
    Coverage::full("awesome_oscillator"),
    Coverage::full("ppo"),
    Coverage::full("wavetrend"),
    Coverage::full("cmo"),
    Coverage::full("elder_ray"),
    Coverage::full("connors_rsi"),
    Coverage::full("coppock"),
    Coverage::full("dpo"),
    Coverage::full("kst"),
    Coverage::full("rvi"),
    Coverage::full("bop"),
    Coverage::full("bbtrend"),
    Coverage::full("zscore"),
];

// --- macd --------------------------------------------------------------------------------------

#[test]
fn macd_defaults() {
    holds("macd_defaults", "macd", IndicatorUnit::Unitless);
}

#[test]
fn macd_short() {
    holds("macd_short", "macd", IndicatorUnit::Unitless);
}

#[test]
fn macd_flat() {
    holds("macd_flat", "macd", IndicatorUnit::Unitless);
}

#[test]
fn macd_rejects_invalid_configuration() {
    assert_rejected("macd", &[("fast_len", 0.0)]);
    assert_rejected("macd", &[("signal_len", 2.5)]);
    assert_rejected("macd", &[("fast_len", 26.0), ("slow_len", 26.0)]);
    assert_rejected("macd", &[("fast", 12.0)]);
}

